function buildMetaballs(centers, radii, iso, bounds, h, epsilon):
  require len(centers) == len(radii) and len(centers) > 0
  require iso > 0 and h > 0
  regularized = epsilon is not null
  if regularized: require epsilon > 0
  grid = makeGrid(bounds, h)
  for p in grid.nodes:
    F = 0
    for i in 0..len(centers)-1:
      r2 = squaredDistance(p, centers[i])
      if regularized:
        F += radii[i]^2 / (r2 + epsilon^2)
      else if r2 == 0:
        F = +infinity
        break
      else:
        F += radii[i]^2 / r2
    grid.value[p] = F
  return validateMesh(marchingCubes(grid, iso))

function radiusAt(s, keys, L_body):
  require L_body > 0 and strictlyIncreasing(keys.s)
  s = clamp(s, keys[0].s, keys[last].s)
  i = binarySearchSegment(keys.s, s)
  ds = keys[i+1].s - keys[i].s
  u = (s - keys[i].s) / ds
  m0,m1 = monotoneTangents(keys, i)
  r = h00(u)*keys[i].r + h10(u)*ds*m0 + h01(u)*keys[i+1].r + h11(u)*ds*m1
  if r < -tolerance: fail("negative radius overshoot")
  return max(0, r)

function updatePupil(e, target, n, radius, contour, lastDir):
  v = target - e
  if length(v) <= epsilonLength: return keepPrevious(e, lastDir)
  g = normalize(v)
  t = g - dot(g,n)*n
  if length(t) <= epsilonDirection: t = fallbackTangent(n,lastDir)
  u = normalize(t)
  offset = clampToContour(radius*u, contour)
  return {position:e+offset, direction:normalize(offset or u)}

function fabrik(root, target, lengths, positions, epsilon, maxIter):
  R = sum(lengths)
  d = distance(root, target)
  if d > R:
    dir = normalizeOrFallback(target-root)
    positions[0] = root
    for i in 0..len(lengths)-1:
      positions[i+1] = positions[i] + lengths[i]*dir
    return {positions, reachable:false}
  for iter in 1..maxIter:
    positions[last] = target
    for i from last-1 downto 0:
      dir = normalizeOrPrevious(positions[i]-positions[i+1])
      positions[i] = positions[i+1] + lengths[i]*dir
    positions[0] = root
    for i in 0..last-1:
      dir = normalizeOrPrevious(positions[i+1]-positions[i])
      positions[i+1] = positions[i] + lengths[i]*dir
    if distance(positions[last],target) <= epsilon:
      return {positions, reachable:true, converged:true}
  return {positions, reachable:true, converged:false}

function skinDQSBounded(vertex, influences, dualBones, nMax):
  require 1 <= nMax <= shaderInfluenceLimit
  kept = stableSortByWeightThenBoneId(influences).take(nMax)
  total = sum(kept.weights)
  if total <= weightEpsilon: failVertex(vertex)
  normalizeWeights(kept,total)
  return dqsBlendAndTransform(vertex, kept, dualBones)
